with target as(select * from public.works where id=any(array[]::bigint[]) or open_library_id=any(array['OL2240623W','OL2240630W','OL2240638W','OL2240645W','OL2240654W','OL2240660W','OL2240661W']::text[]) or regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['demuzeinhetkolenhok','doodaandegrutters','hetkroostvanaagtmorsebel','kijkenisbekekenworden','overdenoodzaakvantuinieren','verzonkenboeken','vreemdpakhuis']::text[]) or id in(select work_id from public.catalog_work_title_aliases where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['demuzeinhetkolenhok','doodaandegrutters','hetkroostvanaagtmorsebel','kijkenisbekekenworden','overdenoodzaakvantuinieren','verzonkenboeken','vreemdpakhuis']::text[]))),a as(select * from public.authors where id in(select author_id from target) or open_library_id=any(array['OL289798A']::text[]) or regexp_replace(lower(normalize(name,NFD)),'[^a-z0-9]','','g')=any(array['gerritjankomrij','gerritkomrij','gerrirkomrij']::text[])),e as(select * from public.editions where work_id in(select id from target) or open_library_edition_id=any(array['OL3233549M','OL4343696M','OL3045770M','OL613473M','OL1283246M','OL2425436M','OL12800370M']::text[]) or regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789070532093','9789061877011','9789060052228','9789029526739','9789035110557','9789029527194','9789023462392']::text[])) select jsonb_build_object('project','qvplwejffhjvxaypmjut','checked_at',clock_timestamp(),'works',coalesce((select jsonb_agg(to_jsonb(t) order by id) from target t),'[]'),'authors',coalesce((select jsonb_agg(to_jsonb(t) order by id) from a t),'[]'),'author_corpora',coalesce((select jsonb_agg(to_jsonb(t) order by id) from public.works t where author_id in(select id from a)),'[]'),'editions',coalesce((select jsonb_agg(to_jsonb(t) order by id) from e t),'[]'),'metadata',coalesce((select jsonb_agg(to_jsonb(t) order by edition_id) from public.catalog_edition_metadata t where edition_id in(select id from e)),'[]'),'descriptions',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,language) from public.catalog_work_descriptions t where work_id in(select id from target)),'[]'),'aliases',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,title) from public.catalog_work_title_aliases t where work_id in(select id from target)),'[]')) as snapshot;
